import re

import pytest


def title_of(html: str) -> str:
    """Return the text between the first <title> and </title> tags in html.

    The html string is already fetched; this function must not use the network.
    Tag matching is case-insensitive. Returns an empty string when no
    complete <title>...</title> pair is present.
    """
    match = re.search(r"<title>(.*?)</title>", html, re.IGNORECASE | re.DOTALL)
    if match is None:
        return ""
    return match.group(1)


def test_simple_title() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_uppercase_tags() -> None:
    assert title_of("<HTML><TITLE>Shout</TITLE></HTML>") == "Shout"


def test_mixed_case_tags() -> None:
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_missing_title_returns_empty() -> None:
    assert title_of("<html><body>no title here</body></html>") == ""


def test_empty_title_returns_empty() -> None:
    assert title_of("<title></title>") == ""


def test_empty_input_returns_empty() -> None:
    assert title_of("") == ""


def test_unclosed_title_returns_empty() -> None:
    assert title_of("<title>Never closed") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>First</title><title>Second</title>") == "First"


def test_title_spanning_lines() -> None:
    assert title_of("<title>Line one\nLine two</title>") == "Line one\nLine two"


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        ("<title>A</title>", "A"),
        ("<head><title>B</title></head>", "B"),
        ("<title> padded </title>", " padded "),
    ],
)
def test_title_parametrized(html: str, expected: str) -> None:
    assert title_of(html) == expected
